"""Snapping span times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.models import Span


def _snap(minute: int, step: int) -> int:
    return (2 * minute + step) // (2 * step) * step


def _clock(minute: int) -> str:
    return '{:02d}:{:02d}'.format(*divmod(minute, 60))


# ---
def rounded_labels(spans: Iterable[Span], step: int) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m), times snapped to step."""
    if step <= 0 or 60 % step:
        raise ValueError(
            'step must divide an hour: {}'.format(step)
        )
    labels = []
    for span in spans:
        start = _snap(span.start, step)
        end = _snap(span.end, step)
        hours, mins = divmod(end - start, 60)
        labels.append('{}-{} ({}h {}m)'.format(
            _clock(start), _clock(end), hours, mins
        ))
    return labels
