cat > tests/test_rounding.py <<'EOF'
import unittest

from hourglass.models import Span
from hourglass.rounding import rounded_labels


class RoundingTests(unittest.TestCase):
    def test_snaps_to_step(self):
        spans = [Span(8 * 60 + 53, 17 * 60 + 11)]
        self.assertEqual(
            rounded_labels(spans, 15), ['09:00-17:15 (8h 15m)']
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 270)]
        self.assertEqual(
            rounded_labels(spans, 30),
            ['01:00-02:00 (1h 0m)', '03:00-04:30 (1h 30m)'],
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)


if __name__ == '__main__':
    unittest.main()
